#!/usr/bin/env node
// Conservative uninstall of files generated by the current Agentic SDLC release.
import { existsSync, lstatSync, readFileSync, unlinkSync, readdirSync, rmdirSync } from 'node:fs'
import { dirname, join, relative, resolve, sep } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseArgs, plannedFiles } from './sdlc-install.mjs'

const SOURCE = resolve(dirname(fileURLToPath(import.meta.url)), '..')

function inspect(target, path, content) {
  const dest = join(target, path)
  let current = target
  for (const part of relative(target, dest).split(sep)) {
    if (part === '.' || part === '..' || !part) return { path, status: 'unsafe-path' }
    current = join(current, part)
    if (existsSync(current) && lstatSync(current).isSymbolicLink()) return { path, status: 'unsafe-path' }
  }
  if (!existsSync(dest)) return { path, status: 'missing' }
  if (!lstatSync(dest).isFile()) return { path, status: 'not-file' }
  return readFileSync(dest).equals(Buffer.from(content))
    ? { path, status: 'managed' } : { path, status: 'modified' }
}

export function uninstall({ target, platforms, apply = false }, source = SOURCE) {
  target = resolve(target)
  if (!existsSync(target) || !lstatSync(target).isDirectory() || lstatSync(target).isSymbolicLink()) {
    throw new Error('Target must be an existing non-symlink directory')
  }
  const expected = plannedFiles(platforms, source)
  const inspected = [...expected].map(([path, content]) => inspect(target, path, content))
  const blocked = inspected.filter(x => !['missing', 'managed'].includes(x.status))
  const managed = inspected.filter(x => x.status === 'managed')
  if (!apply || blocked.length) return { applied: false, ready: !blocked.length,
    managed: managed.length, blocked, missing: inspected.length - managed.length - blocked.length }
  // Preflight completed. Never remove a directory that contains unrelated files.
  const dirs = new Set()
  for (const item of managed) {
    const dest = join(target, item.path)
    // Re-check the leaf immediately before unlinking to reject changed contents.
    const expectedContent = expected.get(item.path)
    if (!lstatSync(dest).isFile() || !readFileSync(dest).equals(Buffer.from(expectedContent))) {
      throw new Error(`File changed during uninstall: ${item.path}`)
    }
    unlinkSync(dest)
    let parent = dirname(dest)
    while (parent !== target && parent.startsWith(target + sep)) {
      dirs.add(parent)
      parent = dirname(parent)
    }
  }
  for (const dir of [...dirs].sort((a, b) => b.length - a.length)) {
    if (existsSync(dir) && lstatSync(dir).isDirectory() && !lstatSync(dir).isSymbolicLink() &&
        readdirSync(dir).length === 0) rmdirSync(dir)
  }
  return { applied: true, ready: true, removed: managed.length, missing: inspected.length - managed.length,
    blocked: [] }
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const argv = process.argv.slice(2)
    const apply = argv.includes('--apply')
    const opts = parseArgs(argv.filter(arg => arg !== '--apply'))
    const report = uninstall({ ...opts, apply })
    process.stdout.write(JSON.stringify(report, null, 2) + '\n')
    if (!report.ready) process.exitCode = 2
  } catch (error) {
    process.stderr.write(`sdlc uninstall: ${error.message}\n`)
    process.exitCode = 1
  }
}
